def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space‑separated string.

    Parameters
    ----------
    parser : argparse.ArgumentParser
        The parser whose flags are to be extracted.

    Returns
    -------
    str
        A string containing all option flags (e.g. ``-h --help``) in the order
        they appear in the parser.
    """
    flags = []
    for action in parser._actions:
        # ``option_strings`` contains the flag names for optional arguments.
        for opt in action.option_strings:
            if opt.startswith('-'):
                flags.append(opt)
    return ' '.join(flags)
```

