def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old)."""

    try:
        data = json.loads(document)
        # Expect keys: subject, aliases, links
        return data
    except json.JSONDecodeError:
        # parse XRD
        root = ET.fromstring(document)
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        result = {}
        subject = root.find('xrd:Subject', ns)
        if subject is not None:
            result['subject'] = subject.text
        aliases = root.findall('xrd:Alias', ns)
        if aliases:
            result['aliases'] = [a.text for a in aliases]
        links = []
        for link in root.findall('xrd:Link', ns):
            l = {}
            for attr in ['rel', 'type', 'href', 'template']:
                val = link.get(attr)
                if val:
                    l[attr] = val
            if l:
                links.append(l)
        if links:
            result['links'] = links
        return result

